// AI request logging for every Edge Function (KIT-132). Written by hand, not generated by scripts/sync-shared.py:
// it is server-only. One ai_requests row per model or speech call: task, model, prompt version, usage, latency and
// outcome. No prompts, answers or transcripts are stored. ai_requests has no RLS policies, so only the service role
// writes it; logging never fails the request it describes.
import { createClient } from "npm:@supabase/supabase-js@2.119.0";

export type AiStatus = "ok" | "error" | "timeout" | "refused" | "invalid_output";

/** The usage fields the Anthropic SDK returns (a subset, so speech services can pass their own). */
export type Usage = {
  input_tokens?: number | null;
  cache_read_input_tokens?: number | null;
  cache_creation_input_tokens?: number | null;
  output_tokens?: number | null;
};

export type AiLogEntry = {
  householdId: string | null;
  task: string;
  model: string;
  promptVersion: string;
  status: AiStatus | string;
  latencyMs: number;
  usage?: Usage | null;
  /** For speech services: characters (text to speech) or seconds (speech to text), stored as input units. */
  units?: number;
  error?: string | null;
};

const STATUSES = new Set(["ok", "error", "timeout", "refused", "invalid_output"]);

/**
 * The row to insert. Cache writes are added to input tokens (priced at the base input rate in reports); cache reads
 * are kept apart because they cost a tenth or less. Errors are cut to 500 characters.
 */
export function aiRequestRow(e: AiLogEntry) {
  const u = e.usage ?? null;
  const input = u ? (u.input_tokens ?? 0) + (u.cache_creation_input_tokens ?? 0) : e.units ?? null;
  return {
    household_id: e.householdId || null,
    task: e.task,
    model: e.model,
    prompt_version: e.promptVersion,
    input_tokens: input === null ? null : Math.max(0, Math.round(input)),
    cached_tokens: u?.cache_read_input_tokens ?? null,
    output_tokens: u?.output_tokens ?? null,
    latency_ms: Math.max(0, Math.round(e.latencyMs)),
    status: STATUSES.has(e.status) ? e.status : "error",
    error: e.error ? e.error.slice(0, 500) : null,
  };
}

/** Inserts one ai_requests row with the service role; a failure is logged and swallowed. */
export async function logAiRequest(e: AiLogEntry): Promise<void> {
  try {
    const url = Deno.env.get("SUPABASE_URL");
    const key = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
    if (!url || !key) return;
    const admin = createClient(url, key, { auth: { persistSession: false } });
    const { error } = await admin.from("ai_requests").insert(aiRequestRow(e));
    if (error) console.error("ai_requests insert failed", error.message);
  } catch (err) {
    console.error("ai_requests insert failed", err instanceof Error ? err.message : err);
  }
}

/** Times a model call and logs it, whatever happens. The call's own error is rethrown. */
export async function timedAiCall<T extends { usage?: Usage | null; stop_reason?: string | null }>(
  meta: Omit<AiLogEntry, "status" | "latencyMs" | "usage" | "error">,
  call: () => Promise<T>,
  judge: (r: T) => { status: AiStatus; error?: string } = (r) => ({ status: r.stop_reason === "refusal" ? "refused" : "ok" }),
): Promise<T> {
  const started = Date.now();
  try {
    const r = await call();
    const v = judge(r);
    await logAiRequest({ ...meta, ...v, latencyMs: Date.now() - started, usage: r.usage ?? null });
    return r;
  } catch (err) {
    const name = err instanceof Error ? err.name : "";
    const message = err instanceof Error ? err.message : String(err);
    await logAiRequest({ ...meta, status: /timeout/i.test(name + message) ? "timeout" : "error", latencyMs: Date.now() - started, error: message });
    throw err;
  }
}
